STORIES_GENRE_4 = [{'id': '031', 'title_vi': 'Hai Mươi Chín', 'title_cn': '二十九', 'author': 'Ninh Mông Ảnh Thị (柠萌影视)', 'platform': 'Douyin (Hiện tượng đoản kịch 1.4 tỷ view · Dương Dung đóng chính)', 'category': 'Hiện đại đô thị / Song nữ chủ / Đi bài chống tiểu tam truyền thống / Tự chủ tài chính', 'premise': "Viên Bùi – người phụ nữ 29 tuổi toàn tâm làm nội trợ, phát hiện chồng mình ngoại tình với Lục Tiêu Sam – nữ quản lý tại một cửa hàng đồ hiệu xa xỉ. Thay vì xông đến đánh ghen xé áo như mô-típ thông thường, Viên Bùi giấu kín thân phận, nộp hồ sơ xin việc làm nhân viên bán hàng cấp dưới của chính 'tình địch'. Hai người phụ nữ từ thế đối đầu dần nhận ra bộ mặt thật đê hèn, lợi dụng của gã đàn ông tồi tệ và bắt tay nhau trừng trị kẻ bội bạc.", 'characters': ['Viên Bùi (Chính thê): Điềm đạm, có trình độ kiểm toán cao cấp, kiên nhẫn quan sát và thu thập chứng cứ tài chính. Mỏ neo: Chiếc vòng tay hàng hiệu bị cạo số sê-ri.', 'Lục Tiêu Sam (Tiểu tam bị lừa): Sắc sảo, tham vọng vươn lên trong ngành bán lẻ xa xỉ, ngỡ rằng gã đàn ông sắp ly hôn để cưới mình nhưng hóa ra chỉ bị coi là công cụ rửa tiền. Mỏ neo: Bảng chỉ tiêu doanh số cửa hàng.', 'Trang Vĩ (Gã chồng tồi): Đạo mạo, dùng tiền của vợ cũ bao nuôi người mới, giấu giếm các khoản nợ xấu khổng lồ.'], 'hook_3s': "Tôi mặc bộ đồng phục nhân viên thực tập, cúi người thắt lại dây giày cho nữ quản lý cửa hàng đồ hiệu: 'Quản lý Lục, thắt lưng cá sấu anh Trang Vĩ tặng cô tối qua... là dùng thẻ phụ của tôi quẹt đấy'.", 'act_structure': {'act_1': 'Hồi 1 (Thâm nhập sào huyệt): Chính thê đi làm nhân viên bán hàng cạnh tiểu tam, chứng kiến gã chồng dùng lời đường mật lừa dối cả hai người phụ nữ.', 'act_2': 'Hồi 2 (Thức tỉnh liên minh): Viên Bùi đưa ra bản báo cáo tài chính cho thấy gã đàn ông đang chuyển nhượng tài sản công ty đứng tên tiểu tam để trốn nợ; hai người phụ nữ bắt tay nhau lập bẫy pháp lý.', 'act_3': 'Hồi 3 (Đòn trừng phạt sòng phẳng): Tại lễ kỷ niệm thành lập công ty, hai người phụ nữ công khai bản sao kê rút ruột công trình và đơn ly hôn, tống gã đàn ông vào vòng lao lý; cùng nhau mở chuỗi cửa hàng thời trang độc lập.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Triệt tiêu hoàn toàn sự tranh giành đàn ông độc hại (Anti-Catfight). Kẻ thù của phụ nữ không phải người phụ nữ khác, mà là kẻ lừa đảo lợi dụng tình cảm và lòng tin của họ.', 'mastery_takeaways': ['Liên minh Nữ quyền hiện đại (Girls Help Girls): Đổi mới tư duy biên kịch gia đấu, biến xung đột đối kháng thành liên minh trừng trị kẻ có tội, tạo điểm sảng văn minh.', 'Chi tiết ngành hàng xa xỉ: Đạo cụ túi xách Hermes, thắt lưng da cá sấu, mã vạch hóa đơn tạo cảm giác sang trọng và chân thực.', 'Mẹo chuyển thể Audio TikTok: Nhịp thoại đanh thép, tốc độ 1.3x, kết hợp tiếng gõ bàn phím trích xuất file Excel kiểm toán ngân hàng.'], 'title_vn': 'Hai Mươi Chín', 'genre': 'Hiện đại đô thị / Song nữ chủ / Đi bài chống tiểu tam truyền thống / Tự chủ tài chính', 'golden_hook': "Tôi mặc bộ đồng phục nhân viên thực tập, cúi người thắt lại dây giày cho nữ quản lý cửa hàng đồ hiệu: 'Quản lý Lục, thắt lưng cá sấu anh Trang Vĩ tặng cô tối qua... là dùng thẻ phụ của tôi quẹt đấy'.", 'author_platform': 'Ninh Mông Ảnh Thị (柠萌影视) - Douyin (Hiện tượng đoản kịch 1.4 tỷ view · Dương Dung đóng chính)', 'core_lessons': ['Liên minh Nữ quyền hiện đại (Girls Help Girls): Đổi mới tư duy biên kịch gia đấu, biến xung đột đối kháng thành liên minh trừng trị kẻ có tội, tạo điểm sảng văn minh.', 'Chi tiết ngành hàng xa xỉ: Đạo cụ túi xách Hermes, thắt lưng da cá sấu, mã vạch hóa đơn tạo cảm giác sang trọng và chân thực.', 'Mẹo chuyển thể Audio TikTok: Nhịp thoại đanh thép, tốc độ 1.3x, kết hợp tiếng gõ bàn phím trích xuất file Excel kiểm toán ngân hàng.']}, {'id': '032', 'title_vi': 'Mẹ Chồng Cướp Tiền Sính Lễ Của Ta', 'title_cn': '婆婆抢了我的彩礼后', 'author': 'Tri Hồ', 'platform': 'Zhihu (Chuyên mục Gia đình cực phẩm)', 'category': 'Hiện đại đô thị / Mẹ chồng nàng dâu / Cắt dòng tiền / Vả mặt cực phẩm', 'premise': "Ngày cưới, mẹ chồng mặt dày giữ lại toàn bộ 800 triệu tiền sính lễ nhà gái trao cho hai vợ chồng với lý do 'giữ hộ để mua nhà cho em trai chồng cưới vợ'. Chồng nhu nhược khuyên cô nhẫn nhịn vì đạo hiếu. Nữ chính – một chuyên gia phân tích rủi ro tín dụng ngân hàng, mỉm cười đồng ý, sau đó lập tức rút lại căn hộ chung cư cao cấp đứng tên bố mẹ cô mà gia đình chồng đang ở nhờ, đồng thời phong tỏa luôn tài khoản bảo lãnh vay mua xe hơi của em trai chồng.", 'characters': ['Hạ Lan (Nàng dâu): Tỉnh táo, sắc bén, nắm trong tay toàn bộ hồ sơ sở hữu nhà đất và thẩm quyền phê duyệt tín dụng. Mỏ neo: Chùm chìa khóa căn hộ gắn thẻ từ thông minh.', 'Mẹ chồng cực phẩm: Tham lam, trọng nam khinh nữ, coi tiền của con dâu là của cải chung của dòng họ nhà chồng.', "Chồng nhu nhược: 'Bảo bối của mẹ', chỉ biết khuyên vợ hy sinh chịu thiệt."], 'hook_3s': "Mẹ chồng giật phăng chiếc phong bì tám trăm triệu sính lễ nhét vào túi áo, cười toe toét: 'Tiền này mẹ giữ mua xe cho thằng út, con dâu ngoan thì đừng tính toán!'. Tôi mỉm cười rút điện thoại gọi bảo vệ: 'Đổi mã khóa cửa căn penthouse ngay lập tức!'.", 'act_structure': {'act_1': 'Hồi 1 (Vơ vét trắng trợn): Mẹ chồng chiếm đoạt tiền mừng cưới và sính lễ, đòi con dâu giao nộp luôn mật khẩu thẻ lương hàng tháng.', 'act_2': 'Hồi 2 (Đòn kinh tế lạnh lùng): Nữ chính yêu cầu công an can thiệp trục xuất gia đình chồng ra khỏi căn penthouse 20 tỷ đứng tên bố mẹ cô trong vòng 24 giờ; ngừng đóng tiền thuê xe Mercedes cho em trai chồng.', 'act_3': 'Hồi 3 (Gậy ông đập lưng ông): Gia đình chồng phải dọn về khu tập thể cũ dột nát; ngân hàng phát lệnh siết nợ xe hơi vì mất người bảo lãnh; mẹ chồng khóc lóc mang trả 800 triệu xin quay lại nhưng cô ném thẳng đơn ly hôn vào mặt chồng.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: 800 triệu sính lễ thực chất là tiền mẹ chồng vay nóng xã hội đen để làm màu ngày cưới; khi bị cô cắt đứt dòng tiền nhà cửa, chủ nợ đã kéo đến phong tỏa toàn bộ đồ đạc của gia đình bà.', 'mastery_takeaways': ['Nguyên tắc Cắt đứt dòng tiền (Cashflow Guillotine): Trong gia đấu hiện đại, vũ khí mạnh nhất không phải cãi vã mà là thu hồi tài sản và quyền lợi kinh tế.', 'Tốc độ xử lý dứt khoát: Hành động ngay trong vòng 24 giờ, không để đối phương có thời gian dùng đạo đức ràng buộc.', 'Mẹo chuyển thể Audio TikTok: Tiếng loa thông báo của ban quản lý tòa nhà yêu cầu trục xuất cư dân vi phạm, tiếng va chạm vali đồ đạc bị tống ra hành lang.'], 'title_vn': 'Mẹ Chồng Cướp Tiền Sính Lễ Của Ta', 'genre': 'Hiện đại đô thị / Mẹ chồng nàng dâu / Cắt dòng tiền / Vả mặt cực phẩm', 'golden_hook': "Mẹ chồng giật phăng chiếc phong bì tám trăm triệu sính lễ nhét vào túi áo, cười toe toét: 'Tiền này mẹ giữ mua xe cho thằng út, con dâu ngoan thì đừng tính toán!'. Tôi mỉm cười rút điện thoại gọi bảo vệ: 'Đổi mã khóa cửa căn penthouse ngay lập tức!'.", 'author_platform': 'Tri Hồ - Zhihu (Chuyên mục Gia đình cực phẩm)', 'core_lessons': ['Nguyên tắc Cắt đứt dòng tiền (Cashflow Guillotine): Trong gia đấu hiện đại, vũ khí mạnh nhất không phải cãi vã mà là thu hồi tài sản và quyền lợi kinh tế.', 'Tốc độ xử lý dứt khoát: Hành động ngay trong vòng 24 giờ, không để đối phương có thời gian dùng đạo đức ràng buộc.', 'Mẹo chuyển thể Audio TikTok: Tiếng loa thông báo của ban quản lý tòa nhà yêu cầu trục xuất cư dân vi phạm, tiếng va chạm vali đồ đạc bị tống ra hành lang.']}, {'id': '033', 'title_vi': 'Trọng Sinh Mẹ Chồng Cùng Xuyên Qua Nàng Dâu', 'title_cn': '重生婆婆与穿越儿媳', 'author': 'Tri Hồ', 'platform': 'Zhihu (Hài hước gia đình / Song nữ chủ)', 'category': 'Hiện đại / Trọng sinh & Xuyên không / Mẹ chồng nàng dâu liên thủ / Trị tra nam', 'premise': "Bà mẹ chồng kiếp trước chịu thương chịu khó hầu hạ chồng con nhưng cuối đời bị ông chồng vũ phu đánh đập, đứa con trai cưng đuổi ra công viên chết cóng. Trọng sinh lại, bà quyết định không làm trâu làm ngựa nữa. Đúng lúc đó, con dâu mới cưới lại là một nữ luật sư hiện đại xuyên không về. Hai người phụ nữ vừa chạm mắt nhau đã nhận ra đồng đội, lập tức bắt tay nhau lập nên 'Hiệp hội dâu mẹ trừ khử hai gã đàn ông ăn bám'.", 'characters': ['Mẹ chồng trọng sinh (Bà Lý): Hiểu rõ mọi mưu mô bẩn thỉu của gã chồng gia trưởng, kiếp này chỉ thích đi khiêu vũ và tiêu tiền. Mỏ neo: Chiếc váy hoa rực rỡ và thẻ tập gym.', 'Con dâu xuyên không (Tiểu Triệu): Luật sư sắc sảo, mở miệng là trích dẫn Luật Hôn nhân gia đình và Bộ luật Dân sự. Mỏ neo: Chiếc máy tính xách tay dán hình cán cân công lý.', 'Bố chồng & Con trai: Hai gã đàn ông gia trưởng, lười biếng, ngơ ngác khi thấy cơm không ai nấu, quần áo không ai giặt.'], 'hook_3s': "Bố chồng đập bàn quát: 'Đến giờ cơm rồi sao hai đứa đàn bà chúng mày chưa vào bếp?'. Mẹ chồng thản nhiên vắt chân chữ ngũ, con dâu đưa ra bản hóa đơn dịch vụ: 'Phí nấu một bữa năm trăm nghìn, thanh toán trước mới bật bếp!'.", 'act_structure': {'act_1': "Hồi 1 (Màn chào hỏi giữa hai linh hồn tỉnh táo): Nàng dâu vừa xuyên đến định phản kháng mẹ chồng thì bà mẹ chồng đã nhét cho cô miếng đùi gà: 'Ăn đi con, để tiền đó mẹ con mình đi spa'.", 'act_2': 'Hồi 2 (Chiến dịch đình công): Hai mẹ con cùng nhau đi du lịch, rút sạch tiền gửi chung, để hai bố con ở nhà tự giặt quần áo làm cháy máy giặt và ăn mì tôm ngộ độc.', 'act_3': 'Hồi 3 (Phân chia gia tài): Mẹ chồng nộp đơn ly hôn chia đôi căn nhà; con dâu nộp đơn ly hôn đòi bồi thường thanh xuân; hai người phụ nữ vui vẻ dọn sang căn hộ cao cấp mới mua ở cạnh nhau.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Con trai cưng của bố chồng thực chất là con riêng của bà vợ bé năm xưa tráo đổi; mẹ chồng trọng sinh đã nắm sẵn kết quả xét nghiệm ADN, khiến ông bố chồng phát điên vì nuôi con tu hú suốt 30 năm.', 'mastery_takeaways': ["Đảo ngược quan hệ thù địch truyền thống: Biến 'Mẹ chồng vs Nàng dâu' từ đối đầu một mất một còn thành liên minh phòng thủ, tạo cảm giác mới lạ, ấm áp và cực kỳ hài hước.", 'Hài hước châm biếm sâu cay: Lấy sự lười biếng và bất tài của những kẻ gia trưởng làm chất liệu gây cười sảng khoái.', 'Mẹo chuyển thể Audio TikTok: Tiếng cười rúc rích của hai người phụ nữ xen lẫn tiếng thở hồng hộc bất lực của hai gã đàn ông gia trưởng.'], 'title_vn': 'Trọng Sinh Mẹ Chồng Cùng Xuyên Qua Nàng Dâu', 'genre': 'Hiện đại / Trọng sinh & Xuyên không / Mẹ chồng nàng dâu liên thủ / Trị tra nam', 'golden_hook': "Bố chồng đập bàn quát: 'Đến giờ cơm rồi sao hai đứa đàn bà chúng mày chưa vào bếp?'. Mẹ chồng thản nhiên vắt chân chữ ngũ, con dâu đưa ra bản hóa đơn dịch vụ: 'Phí nấu một bữa năm trăm nghìn, thanh toán trước mới bật bếp!'.", 'author_platform': 'Tri Hồ - Zhihu (Hài hước gia đình / Song nữ chủ)', 'core_lessons': ["Đảo ngược quan hệ thù địch truyền thống: Biến 'Mẹ chồng vs Nàng dâu' từ đối đầu một mất một còn thành liên minh phòng thủ, tạo cảm giác mới lạ, ấm áp và cực kỳ hài hước.", 'Hài hước châm biếm sâu cay: Lấy sự lười biếng và bất tài của những kẻ gia trưởng làm chất liệu gây cười sảng khoái.', 'Mẹo chuyển thể Audio TikTok: Tiếng cười rúc rích của hai người phụ nữ xen lẫn tiếng thở hồng hộc bất lực của hai gã đàn ông gia trưởng.']}, {'id': '034', 'title_vi': 'Chồng Yêu Con Gái Người Giúp Việc, Ta Thành Toàn', 'title_cn': '丈夫爱上保姆女儿', 'author': 'Tri Hồ', 'platform': 'Zhihu (Ngược tra sảng văn)', 'category': 'Hiện đại đô thị / Hôn nhân tan vỡ / Vả mặt bạch liên hoa / Thu hồi tài sản', 'premise': "Chồng của Lâm Hân mê mẩn con gái người giúp việc vì cô ta 'ngây thơ, mộc mạc và không sặc mùi tiền bạc như cô'. Anh ta lén lút tặng nhẫn kim cương, xe sang và đưa cô ta vào công ty của gia đình Lâm Hân làm trợ lý. Lâm Hân không hề đánh ghen; cô lặng lẽ thu thập toàn bộ chứng cứ tham ô, sang tên lại các tài sản mang họ Lâm, rồi hào phóng tổ chức một đám cưới lộng lẫy tác hợp cho đôi tình nhân cùng khoản nợ 50 tỷ kèm theo.", 'characters': ['Lâm Hân: Đại tiểu thư gia tộc kinh doanh thực phẩm, phong thái quý phái, ra đòn chính xác như bác sĩ phẫu thuật. Mỏ neo: Tệp tài liệu kiểm toán dán nhãn tuyệt mật.', 'Gã chồng vong ân: Xuất thân nghèo khó được nhà vợ nâng đỡ nhưng luôn tự ái hão huyền, căm ghét mùi tiền của giới thượng lưu.', "Con gái người giúp việc: Giả vờ thanh cao 'em chỉ yêu tâm hồn của anh', nhưng tay luôn lăm lăm đòi túi xách hàng hiệu."], 'hook_3s': "Chồng tôi đẩy đĩa bánh rán của con gái người giúp việc sang trước mặt tôi: 'Lâm Hân, cô ấy tuy nghèo nhưng tâm hồn thanh khiết, không thực dụng như cô!'. Tôi cười khẩy: 'Thanh khiết mà quẹt thẻ của tôi ba trăm triệu mua túi xách à?'.", 'act_structure': {'act_1': 'Hồi 1 (Màn kịch thanh cao): Đôi tình nhân vụng trộm sau lưng, dùng tiền của nữ chính để thể hiện tình yêu lãng mạn nơi công sở.', 'act_2': 'Hồi 2 (Thành toàn hào phóng): Nữ chính chủ động ký đơn ly hôn, để lại cho gã chồng chức Tổng giám đốc của công ty con đang gánh khoản nợ trái phiếu 50 tỷ chuẩn bị đáo hạn.', 'act_3': "Hồi 3 (Đại sụp đổ): Ngày cưới của đôi tình nhân, tòa án ập vào niêm phong toàn bộ xe cộ, nhà cửa; cô gái 'thanh khiết' lập tức ôm số tiền cọc còn lại bỏ trốn, để mặc gã đàn ông nhảy cầu vì vỡ nợ."}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Con gái người giúp việc từ đầu đã cấu kết với đối thủ cạnh tranh của công ty; cô ta tiếp cận gã chồng chỉ để đánh cắp công thức sản xuất độc quyền, nhưng công thức cô ta lấy được là bản thử nghiệm gây ngộ độc do Lâm Hân cố ý gài lại.', 'mastery_takeaways': ["Công thức 'Thành toàn cho kẻ phản bội' (Let Them Have Each Other): Đòn trả thù tàn nhẫn nhất là tước bỏ tiền bạc và ép hai kẻ phản bội phải sống chung với nhau trong cảnh nghèo đói cùng cực.", "Bóc trần sự đạo đức giả: Tương phản giữa lời nói 'không cần tiền' và hành vi quẹt thẻ liên tục tạo sự thỏa mãn khi kẻ phản diện bị vạch trần.", "Mẹo chuyển thể Audio TikTok: Tiếng quẹt thẻ POS báo lỗi 'Giao dịch bị từ chối do thẻ đã bị khóa', tiếng MC đám cưới ngơ ngác khi công an bước vào sảnh."], 'title_vn': 'Chồng Yêu Con Gái Người Giúp Việc, Ta Thành Toàn', 'genre': 'Hiện đại đô thị / Hôn nhân tan vỡ / Vả mặt bạch liên hoa / Thu hồi tài sản', 'golden_hook': "Chồng tôi đẩy đĩa bánh rán của con gái người giúp việc sang trước mặt tôi: 'Lâm Hân, cô ấy tuy nghèo nhưng tâm hồn thanh khiết, không thực dụng như cô!'. Tôi cười khẩy: 'Thanh khiết mà quẹt thẻ của tôi ba trăm triệu mua túi xách à?'.", 'author_platform': 'Tri Hồ - Zhihu (Ngược tra sảng văn)', 'core_lessons': ["Công thức 'Thành toàn cho kẻ phản bội' (Let Them Have Each Other): Đòn trả thù tàn nhẫn nhất là tước bỏ tiền bạc và ép hai kẻ phản bội phải sống chung với nhau trong cảnh nghèo đói cùng cực.", "Bóc trần sự đạo đức giả: Tương phản giữa lời nói 'không cần tiền' và hành vi quẹt thẻ liên tục tạo sự thỏa mãn khi kẻ phản diện bị vạch trần.", "Mẹo chuyển thể Audio TikTok: Tiếng quẹt thẻ POS báo lỗi 'Giao dịch bị từ chối do thẻ đã bị khóa', tiếng MC đám cưới ngơ ngác khi công an bước vào sảnh."]}, {'id': '035', 'title_vi': 'Phù Đệ Ma Đích Phá Diệt', 'title_cn': '扶弟魔的破灭', 'author': 'Tri Hồ', 'platform': 'Zhihu (Chuyên mục Gia đình mâu thuẫn)', 'category': 'Hiện đại thực tế / Chồng bao nuôi em trai / Cực phẩm thân thích / Tẩy trắng tài chính', 'premise': "Chồng của Bạch Lam là một 'Phù Đệ Ma' (kẻ cuồng nâng đỡ em trai) chính hiệu: Giấu vợ rút 1 tỷ tiền tiết kiệm dưỡng già của bố mẹ vợ cho em trai mua nhà cưới vợ, bắt con gái nhịn học thêm để em trai mua xe sang. Đỉnh điểm là khi em trai gây tai nạn chết người, anh ta bắt vợ phải ký giấy thế chấp căn nhà duy nhất để bồi thường. Bạch Lam quyết định dứt áo ra đi, để mặc cả gia đình nhà chồng tự cắn xé nhau trong đống nợ nần.", 'characters': ['Bạch Lam: Kỹ sư phần mềm, độc lập, từng vì yêu mà nhẫn nhịn nhưng một khi chạm vào ranh giới con cái thì quyết liệt như sư tử. Mỏ neo: Chiếc USB chứa sao kê lịch sử giao dịch ngân hàng 5 năm.', 'Trần Cường (Chồng): Ngu hiếu mù quáng, coi thể diện của em trai và gia tộc họ Trần cao hơn mạng sống vợ con.', 'Gia đình em trai: Lười biếng, cờ bạc, coi việc anh chị chu cấp là nghĩa vụ hiển nhiên của vũ trụ.'], 'hook_3s': "Trần Cường cầm bút nhét vào tay tôi, mắt đỏ ngầu gầm lên: 'Ký vào đơn thế chấp nhà đi! Chẳng lẽ cô muốn nhìn em trai tôi đi tù à? Nó là hương hỏa duy nhất của họ Trần đấy!'.", 'act_structure': {'act_1': 'Hồi 1 (Đòi hỏi vô đáy): Em trai gây tai nạn giao thông bỏ trốn, mẹ chồng và chồng ép con dâu bán nhà trả nợ thay.', 'act_2': 'Hồi 2 (Phản đòn pháp lý): Bạch Lam từ chối ký tên, mang bản sao kê chứng minh chồng đã tẩu tán 2 tỷ tài sản chung cho em trai ra tòa yêu cầu thu hồi tài sản bất hợp pháp.', 'act_3': 'Hồi 3 (Tự diệt vong): Tòa tuyên vô hiệu các giao dịch chuyển tiền cho em trai; em trai bị bắt đi tù; mẹ chồng lên cơn đột quỵ vì bị siết nợ; gã chồng quỳ lạy trước cổng công ty cầu xin cô giúp đỡ nhưng chỉ nhận được nụ cười khinh bỉ.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Căn nhà hai vợ chồng đang ở được mua hoàn toàn bằng tiền đền bù giải tỏa của bố mẹ đẻ Bạch Lam trước hôn nhân; cô đã chuyển nhượng quyền sở hữu hợp pháp cho con gái từ 2 năm trước.', 'mastery_takeaways': ["Xử lý dứt khoát với 'Phù Đệ Ma': Không có sự thỏa hiệp với những kẻ bòn rút tài sản gia đình; viện dẫn điều 1060 Bộ luật Dân sự về thu hồi tài sản chung bị tẩu tán tạo uy lực pháp lý tuyệt đối.", 'Khắc họa tâm lý ngu hiếu: Miêu tả chân thực sự mù quáng của kẻ coi trọng họ hàng hơn vợ con để khơi dậy sự phẫn nộ tột cùng của thính giả.', 'Mẹo chuyển thể Audio TikTok: Tiếng đập bàn quát tháo của gã chồng ở giây thứ nhất, chuyển sang tiếng gõ búa tuyên án của thẩm phán ở hồi kết.'], 'title_vn': 'Phù Đệ Ma Đích Phá Diệt', 'genre': 'Hiện đại thực tế / Chồng bao nuôi em trai / Cực phẩm thân thích / Tẩy trắng tài chính', 'golden_hook': "Trần Cường cầm bút nhét vào tay tôi, mắt đỏ ngầu gầm lên: 'Ký vào đơn thế chấp nhà đi! Chẳng lẽ cô muốn nhìn em trai tôi đi tù à? Nó là hương hỏa duy nhất của họ Trần đấy!'.", 'author_platform': 'Tri Hồ - Zhihu (Chuyên mục Gia đình mâu thuẫn)', 'core_lessons': ["Xử lý dứt khoát với 'Phù Đệ Ma': Không có sự thỏa hiệp với những kẻ bòn rút tài sản gia đình; viện dẫn điều 1060 Bộ luật Dân sự về thu hồi tài sản chung bị tẩu tán tạo uy lực pháp lý tuyệt đối.", 'Khắc họa tâm lý ngu hiếu: Miêu tả chân thực sự mù quáng của kẻ coi trọng họ hàng hơn vợ con để khơi dậy sự phẫn nộ tột cùng của thính giả.', 'Mẹo chuyển thể Audio TikTok: Tiếng đập bàn quát tháo của gã chồng ở giây thứ nhất, chuyển sang tiếng gõ búa tuyên án của thẩm phán ở hồi kết.']}, {'id': '036', 'title_vi': 'Bàn Tiệc Đầy Tháng Của Con Gái', 'title_cn': '女儿满月宴', 'author': 'Tri Hồ', 'platform': 'Zhihu (Mẹ chồng cực phẩm / Trọng nam khinh nữ)', 'category': 'Hiện đại gia đình / Trọng nam khinh nữ / Đổi con / Vả mặt ADN', 'premise': 'Tại tiệc đầy tháng của con gái nhỏ, mẹ chồng mang đến một bé trai đỏ hỏn, tuyên bố đây mới là cháu ruột họ Thẩm và ép con dâu phải nhận nuôi, còn đứa con gái vừa sinh ra thì gửi về quê cho họ hàng nuôi hộ. Chồng cô đứng bên cạnh im lặng ngầm đồng thuận. Nữ chính – bác sĩ di truyền học, không nói một lời, thản nhiên bấm micro công chiếu kết quả giám định ADN của cả ba đứa trẻ lên màn hình máy chiếu tiệc cưới.', 'characters': ['Tiêu Dao: Bác sĩ trưởng phòng xét nghiệm di truyền học, ánh mắt sắc sảo, luôn chuẩn bị sẵn mẫu sinh phẩm trước khi đối phương hành động. Mỏ neo: Tấm thẻ xét nghiệm ADN có đóng dấu đỏ của Viện Pháp Y.', 'Mẹ chồng: Mê tín, cuồng cháu trai đến mức mất trí, câu kết với người ngoài để lừa dối con dâu.', 'Chồng: Hèn nhát, sợ mẹ nhưng lại tham lam con trai nối dõi tông đường.'], 'hook_3s': "Mẹ chồng giật phăng đứa con gái một tháng tuổi trên tay tôi ném sang cho người giúp việc: 'Đồ con gái sao chổi! Đây mới là cháu trai đích tôn của nhà này, mày phải nuôi nó!'.", 'act_structure': {'act_1': 'Hồi 1 (Âm mưu đổi cháu giữa tiệc đầy tháng): Mẹ chồng ép nhận con nuôi trước mặt hàng trăm quan khách họ hàng để hợp thức hóa đứa bé trai.', 'act_2': 'Hồi 2 (Chiếu phim xét nghiệm ADN): Tiêu Dao bật màn hình LED hội trường: Đứa bé trai thực chất là con riêng của chồng cô với cô nhân tình bên ngoài, sinh trước con gái cô đúng 3 ngày.', 'act_3': 'Hồi 3 (Thanh trừng gia môn): Bố chồng tức giận tát mẹ chồng và con trai; Tiêu Dao bế con gái bước lên xe của anh trai tài phiệt, tuyên bố khởi kiện giành quyền nuôi con và yêu cầu phân chia tài sản do hành vi ngoại tình có con riêng.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Đứa con riêng đó cũng không phải của chồng cô; kết quả ADN cho thấy đứa bé trai trùng khớp gen với người lái xe riêng của gia đình; gã chồng nuôi con của vợ bé và tài xế suốt thời gian qua.', 'mastery_takeaways': ['Đòn bẻ lái kép (Double ADN Twist): Twist 1 bóc trần ngoại tình -> Twist 2 bóc trần sự phản bội của nhân tình, biến kẻ phản diện thành trò cười cho toàn xã hội.', 'Không gian công cộng kịch tính: Đặt cuộc đối đầu ngay tại tiệc đầy tháng đông người để tối đa hóa sự sụp đổ danh dự của gia đình cực phẩm.', 'Mẹo chuyển thể Audio TikTok: Tiếng khóc the thé của trẻ sơ sinh xen lẫn tiếng ồn ào xôn xao của quan khách khi màn hình máy chiếu bật sáng.'], 'title_vn': 'Bàn Tiệc Đầy Tháng Của Con Gái', 'genre': 'Hiện đại gia đình / Trọng nam khinh nữ / Đổi con / Vả mặt ADN', 'golden_hook': "Mẹ chồng giật phăng đứa con gái một tháng tuổi trên tay tôi ném sang cho người giúp việc: 'Đồ con gái sao chổi! Đây mới là cháu trai đích tôn của nhà này, mày phải nuôi nó!'.", 'author_platform': 'Tri Hồ - Zhihu (Mẹ chồng cực phẩm / Trọng nam khinh nữ)', 'core_lessons': ['Đòn bẻ lái kép (Double ADN Twist): Twist 1 bóc trần ngoại tình -> Twist 2 bóc trần sự phản bội của nhân tình, biến kẻ phản diện thành trò cười cho toàn xã hội.', 'Không gian công cộng kịch tính: Đặt cuộc đối đầu ngay tại tiệc đầy tháng đông người để tối đa hóa sự sụp đổ danh dự của gia đình cực phẩm.', 'Mẹo chuyển thể Audio TikTok: Tiếng khóc the thé của trẻ sơ sinh xen lẫn tiếng ồn ào xôn xao của quan khách khi màn hình máy chiếu bật sáng.']}, {'id': '037', 'title_vi': 'Người Chồng Tiết Kiệm Cực Hạn', 'title_cn': '极限抠门丈夫', 'author': 'Tri Hồ', 'platform': 'Zhihu (Châm biếm hiện đại)', 'category': 'Hiện đại đô thị / Chồng keo kiệt cực phẩm / Tính toán từng cọng hành / Vả mặt ly hôn', 'premise': "Chồng của Diệp Hân mắc chứng keo kiệt bệnh hoạn với vợ con: Bắt vợ dùng lại nước rửa rau để tắm, tính tiền từng quả trứng gà vợ ăn mỗi bữa, thậm chí khi vợ sinh mổ còn từ chối mua mũi tiêm giảm đau vì 'đắt quá phí tiền'. Thế nhưng sau lưng vợ, anh ta chuyển khoản đều đặn mỗi tháng 50 triệu cho mối tình đầu và mua cho cô ta một căn hộ ven hồ. Diệp Hân quyết định lập một 'bảng tính toán chi phí phục vụ' kéo dài 5 năm hôn nhân.", 'characters': ['Diệp Hân: Giám đốc kiểm toán thuế, sở hữu tư duy số liệu hoàn hảo, từng chi tiết nhỏ đều được cô chuyển hóa thành bằng chứng tài chính. Mỏ neo: Tệp hóa đơn chi tiêu dày 200 trang đóng bìa cứng.', "Hứa Đào (Chồng keo kiệt): Chuyên gia đạo đức giả, luôn miệng nói 'tiết kiệm vì tương lai gia đình' nhưng thực chất chỉ coi vợ như nô tì miễn phí.", 'Mối tình đầu: Sống xa hoa bằng tiền mồ hôi nước mắt của vợ chồng Diệp Hân.'], 'hook_3s': "Tôi nằm quằn quại trên bàn sinh mổ, Hứa Đào giật lấy bút từ tay bác sĩ: 'Không tiêm thuốc giảm đau hai triệu! Sinh con ai chẳng đau, cắn răng nhẫn nhịn là qua thôi!'.", 'act_structure': {'act_1': 'Hồi 1 (Cơn ác mộng bủn xỉn): Sau ca sinh mổ đau đớn, nữ chính phát hiện hóa đơn chuyển tiền mua túi xách hiệu Hermes 100 triệu của chồng cho người phụ nữ khác.', 'act_2': 'Hồi 2 (Thu thập nhật ký tiêu xài): Nữ chính trích xuất sao kê ngân hàng bí mật, phát hiện căn hộ ven hồ đứng tên mối tình đầu được mua bằng tiền tích lũy chung trong thời kỳ hôn nhân.', 'act_3': 'Hồi 3 (Đòi lại từng xu một): Khởi kiện ra tòa đòi lại 100% tài sản đã tặng cho tiểu tam do vi phạm trật tự công cộng và thuần phong mỹ tục; tính tiền công giúp việc và chăm sóc con 5 năm với giá thị trường 50 triệu/tháng, ép gã chồng bủn xỉn phải bán xe trả nợ.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Cô bồ nhí không hề yêu gã chồng; ngay khi bị tòa án đòi lại căn hộ, cô ta lập tức công khai toàn bộ tin nhắn mồi chài và video nhạy cảm của hắn lên mạng để trả thù, khiến hắn bị sa thải khỏi công ty.', 'mastery_takeaways': ['Công lý tài chính (Financial Retribution): Dùng chính sự chi li tính toán của kẻ keo kiệt để trừng phạt hắn bằng pháp luật, đòi lại từng đồng từng hào tạo sự hả dạ tột độ.', 'Đánh trúng nỗi đau phụ nữ: Chi tiết mũi tiêm giảm đau khi sinh con là chất xúc tác cảm xúc mạnh nhất khiến người nghe đồng cảm và phẫn nộ.', 'Mẹo chuyển thể Audio TikTok: Tiếng máy in hóa đơn chạy rè rè kéo dài, tiếng gõ búa tòa án dứt khoát kết thúc vụ việc.'], 'title_vn': 'Người Chồng Tiết Kiệm Cực Hạn', 'genre': 'Hiện đại đô thị / Chồng keo kiệt cực phẩm / Tính toán từng cọng hành / Vả mặt ly hôn', 'golden_hook': "Tôi nằm quằn quại trên bàn sinh mổ, Hứa Đào giật lấy bút từ tay bác sĩ: 'Không tiêm thuốc giảm đau hai triệu! Sinh con ai chẳng đau, cắn răng nhẫn nhịn là qua thôi!'.", 'author_platform': 'Tri Hồ - Zhihu (Châm biếm hiện đại)', 'core_lessons': ['Công lý tài chính (Financial Retribution): Dùng chính sự chi li tính toán của kẻ keo kiệt để trừng phạt hắn bằng pháp luật, đòi lại từng đồng từng hào tạo sự hả dạ tột độ.', 'Đánh trúng nỗi đau phụ nữ: Chi tiết mũi tiêm giảm đau khi sinh con là chất xúc tác cảm xúc mạnh nhất khiến người nghe đồng cảm và phẫn nộ.', 'Mẹo chuyển thể Audio TikTok: Tiếng máy in hóa đơn chạy rè rè kéo dài, tiếng gõ búa tòa án dứt khoát kết thúc vụ việc.']}, {'id': '038', 'title_vi': 'Camera Giấu Kín Trong Phòng Tân Hôn', 'title_cn': '婚房里的针孔摄像头', 'author': 'Tri Hồ', 'platform': 'Zhihu (Chuyên mục Pháp lý & Gia đình)', 'category': 'Hiện đại đô thị / Mẹ chồng biến thái / Xâm phạm quyền riêng tư / Pháp luật trừng trị', 'premise': "Vừa cưới xong 3 ngày, nữ chính phát hiện trong mắt gấu bông và ổ cắm điện phòng ngủ tân hôn có gắn camera giấu kín siêu nhỏ truyền hình ảnh trực tiếp về điện thoại mẹ chồng. Khi chất vấn, mẹ chồng trơ trẽn tuyên bố: 'Tao lắp để xem con dâu có hầu hạ con trai tao chu đáo không, nhà này do tao bỏ tiền ra mua thì tao có quyền!'. Nữ chính – phóng viên điều tra an ninh mạng, quyết định tặng bà một bài học nhớ đời trên sóng truyền thông.", 'characters': ['Phương Vi: Phóng viên điều tra dũng cảm, am hiểu thiết bị định vị và luật an ninh thông tin mạng. Mỏ neo: Chiếc máy dò tín hiệu hồng ngoại cầm tay.', 'Mẹ chồng kiểm soát: Ám ảnh tâm lý muốn kiểm soát tuyệt đối cuộc đời con trai, không có ranh giới đạo đức.', "Chồng: Bất lực, coi hành vi xâm phạm của mẹ là 'sự quan tâm thái quá của người lớn'."], 'hook_3s': "Chiếc máy dò hồng ngoại phát ra tiếng 'bíp bíp' chói tai, rọi luồng sáng đỏ vào tròng mắt gấu bông trên đầu giường: Chiếc camera siêu nhỏ đang chớp đèn xanh truyền dữ liệu về máy mẹ chồng.", 'act_structure': {'act_1': 'Hồi 1 (Phát hiện sự xâm phạm tột cùng): Tìm thấy 4 chiếc camera trong phòng ngủ và phòng tắm tân hôn.', 'act_2': 'Hồi 2 (Giữ nguyên hiện trường): Không làm ầm ĩ, Phương Vi mời công an và thừa phát lại đến lập vi bằng tại chỗ, thu giữ thẻ nhớ chứa hàng trăm clip riêng tư.', 'act_3': "Hồi 3 (Khởi tố hình sự): Khởi kiện mẹ chồng ra tòa tội 'Xâm phạm thư tín, điện tín hoặc thông tin riêng tư của người khác'; công khai câu chuyện trong buổi tọa đàm về quyền riêng tư phụ nữ, khiến gia đình nhà chồng không còn mặt mũi nhìn bà con xóm giềng."}, 'plot_twist': "Điểm bẻ lái cốt lõi: Mẹ chồng không chỉ xem một mình; bà ta còn chia sẻ đường link phát sóng phòng ngủ của con dâu cho một nhóm chat các bà cô trong họ để cùng nhau chấm điểm 'nết na' của con dâu; toàn bộ nhóm chat bị xử phạt hành chính và bồi thường tổn thất tinh thần 500 triệu.", 'mastery_takeaways': ['Lập vi bằng chuyên nghiệp (Legal Evidentiary Preservation): Hành động bình tĩnh mời thừa phát lại và công an lập biên bản trước khi rút dây cắm là bài học pháp lý thực chiến đắt giá.', "Bảo vệ ranh giới cá nhân (Personal Boundaries): Đập tan luận điệu 'người trong nhà thì không cần câu nệ riêng tư', khẳng định quyền bất khả xâm phạm về thân thể và đời tư.", 'Mẹo chuyển thể Audio TikTok: Tiếng tít tít máy quét hồng ngoại dồn dập, tiếp nối bằng tiếng đọc biên bản phạm pháp của cảnh sát.'], 'title_vn': 'Camera Giấu Kín Trong Phòng Tân Hôn', 'genre': 'Hiện đại đô thị / Mẹ chồng biến thái / Xâm phạm quyền riêng tư / Pháp luật trừng trị', 'golden_hook': "Chiếc máy dò hồng ngoại phát ra tiếng 'bíp bíp' chói tai, rọi luồng sáng đỏ vào tròng mắt gấu bông trên đầu giường: Chiếc camera siêu nhỏ đang chớp đèn xanh truyền dữ liệu về máy mẹ chồng.", 'author_platform': 'Tri Hồ - Zhihu (Chuyên mục Pháp lý & Gia đình)', 'core_lessons': ['Lập vi bằng chuyên nghiệp (Legal Evidentiary Preservation): Hành động bình tĩnh mời thừa phát lại và công an lập biên bản trước khi rút dây cắm là bài học pháp lý thực chiến đắt giá.', "Bảo vệ ranh giới cá nhân (Personal Boundaries): Đập tan luận điệu 'người trong nhà thì không cần câu nệ riêng tư', khẳng định quyền bất khả xâm phạm về thân thể và đời tư.", 'Mẹo chuyển thể Audio TikTok: Tiếng tít tít máy quét hồng ngoại dồn dập, tiếp nối bằng tiếng đọc biên bản phạm pháp của cảnh sát.']}, {'id': '039', 'title_vi': 'Lúc Bố Chồng Bệnh Nguy', 'title_cn': '公公病危之时', 'author': 'Tri Hồ', 'platform': 'Zhihu (Chuyên mục Tranh đoạt tài sản)', 'category': 'Hiện đại đô thị / Tranh đoạt di sản / Lòng người ấm lạnh / Thấu thị nhân tâm', 'premise': 'Bố chồng bị đột quỵ nằm trong phòng hồi sức cấp cứu nguy kịch, máy thở đang duy trì sự sống từng phút. Ngoài hành lang bệnh viện, các cô con gái và người con trai thứ không một ai hỏi han viện phí, họ xúm lại ép con dâu trưởng giao nộp sổ đỏ căn biệt thự cổ 50 tỷ và thẻ ngân hàng của ông lão. Nữ dâu trưởng – người duy nhất chăm sóc ông cụ suốt 8 năm qua, bình thản rút chiếc máy ghi âm trong túi áo ra.', 'characters': ['Lý Nhã Uyên (Dâu trưởng): Hiếu thảo, thấu tình đạt lý nhưng cứng rắn như thép nguội trước những kẻ tham lam. Mỏ neo: Tờ giấy ủy quyền chăm sóc y tế và chiếc máy ghi âm mini.', 'Đám con ruột bất hiếu: Bỏ mặc cha già 8 năm không một lời thăm hỏi, vừa nghe tin sắp mất liền ùa về đòi chia đất.', 'Bố chồng (Lúc tỉnh táo): Vị thẩm phán về hưu, đã nhìn thấu sự bất hiếu của các con từ nhiều năm trước.'], 'hook_3s': "Tiếng máy thở kêu ngắt quãng trong phòng cấp cứu, cô em chồng đã giật mạnh túi xách của tôi làm rơi vãi đồ đạc: 'Chị dâu! Mau giao chìa khóa két sắt của bố ra đây, đừng hòng nuốt trọn số tiền dưỡng già của ông!'.", 'act_structure': {'act_1': 'Hồi 1 (Cảnh tượng ô nhục nơi bệnh viện): Đám con ruột cãi vã chia chác đất đai ngay trước cửa phòng hồi sức tích cực, từ chối ký giấy đồng ý phẫu thuật nếu chưa có sổ đỏ.', 'act_2': 'Hồi 2 (Cứu người là trên hết): Nữ chính tự mình quẹt thẻ thanh toán 300 triệu viện phí tạm ứng, ký giấy cam kết phẫu thuật cứu sống bố chồng qua cơn nguy kịch.', 'act_3': 'Hồi 3 (Bản di chúc công chứng): Sau khi tỉnh lại, bố chồng công bố bản di chúc lập tại văn phòng công chứng nhà nước: Toàn bộ căn biệt thự 50 tỷ trao tặng riêng cho người con dâu hiếu thảo; đám con bất hiếu mỗi người nhận đúng một đồng xu kỷ niệm.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: Căn biệt thự cổ thực chất không phải của bố chồng; đó là tài sản thuộc sở hữu của riêng mẹ đẻ con dâu trưởng cho ông cụ mượn dưỡng già suốt đời; đám con ruột tranh giành nửa ngày trời một tài sản không hề thuộc về dòng họ mình.', 'mastery_takeaways': ['Tương phản đạo đức sâu sắc: Lòng hiếu thảo vô tư của người dưng (con dâu) đối lập hoàn toàn với sự tàn nhẫn máu lạnh của con ruột ruột thịt.', 'Bài học pháp luật về chăm sóc người cao tuổi: Điều 658 Bộ luật Dân sự về nghĩa vụ phụng dưỡng và quyền tước đoạt quyền thừa kế của con bất hiếu.', 'Mẹo chuyển thể Audio TikTok: Tiếng còi máy theo dõi sinh hiệu bệnh nhân chuyển từ báo động sang nhịp tim ổn định, tiếng ho sặc sụa của đám con khi nhìn bản di chúc.'], 'title_vn': 'Lúc Bố Chồng Bệnh Nguy', 'genre': 'Hiện đại đô thị / Tranh đoạt di sản / Lòng người ấm lạnh / Thấu thị nhân tâm', 'golden_hook': "Tiếng máy thở kêu ngắt quãng trong phòng cấp cứu, cô em chồng đã giật mạnh túi xách của tôi làm rơi vãi đồ đạc: 'Chị dâu! Mau giao chìa khóa két sắt của bố ra đây, đừng hòng nuốt trọn số tiền dưỡng già của ông!'.", 'author_platform': 'Tri Hồ - Zhihu (Chuyên mục Tranh đoạt tài sản)', 'core_lessons': ['Tương phản đạo đức sâu sắc: Lòng hiếu thảo vô tư của người dưng (con dâu) đối lập hoàn toàn với sự tàn nhẫn máu lạnh của con ruột ruột thịt.', 'Bài học pháp luật về chăm sóc người cao tuổi: Điều 658 Bộ luật Dân sự về nghĩa vụ phụng dưỡng và quyền tước đoạt quyền thừa kế của con bất hiếu.', 'Mẹo chuyển thể Audio TikTok: Tiếng còi máy theo dõi sinh hiệu bệnh nhân chuyển từ báo động sang nhịp tim ổn định, tiếng ho sặc sụa của đám con khi nhìn bản di chúc.']}, {'id': '040', 'title_vi': 'Cuộc Chiến Căn Hộ Trường Học Tuyến Một', 'title_cn': '学区房争夺战', 'author': 'Tri Hồ', 'platform': 'Zhihu (Hiện thực xã hội)', 'category': 'Hiện đại đô thị / Tranh đoạt nhà cửa / Cực phẩm gia đình / Rút củi đáy nồi', 'premise': "Căn hộ 80m2 cạnh trường điểm quốc gia của nữ chính mua trước hôn nhân tăng giá lên 30 tỷ. Mẹ chồng và các anh chị em họ hàng nhà chồng họp gia đình ép cô phải chuyển nhượng lại căn hộ với giá 2 tỷ để 'cháu trai họ hàng có hộ khẩu vào lớp 1', hứa sau này cháu thành đạt sẽ nuôi lại cô. Chồng cô đập bàn bảo: 'Cả họ nhờ vả có một lần, em không giúp là đồ ích kỷ độc ác!'. Nữ chính mỉm cười đồng ý, sau đó bán luôn căn hộ cho người mua tiền mặt trong vòng 24 giờ.", 'characters': ['Tống Lam: Chuyên viên môi giới bất động sản cao cấp, nhanh nhẹn, quyết đoán, không có thói quen chần chừ trước những kẻ vô liêm sỉ. Mỏ neo: Hợp đồng công chứng mua bán nhà có chữ ký lăn tay đỏ tươi.', "Mẹ chồng & Họ hàng: Chuyên gia 'đạo đức bắt cóc', dùng tình nghĩa dòng họ để cưỡng đoạt tài sản của người khác.", 'Chồng: Thích sĩ diện với dòng họ, sẵn sàng tước đoạt tương lai của con gái mình để làm vừa lòng người ngoài.'], 'hook_3s': "Chồng tôi ném bản hợp đồng chuyển nhượng hai tỷ lên bàn ăn: 'Ký đi! Căn nhà trường điểm này phải để cho cháu đích tôn của anh vào lớp một, con gái mình học trường làng ở đâu chẳng được!'.", 'act_structure': {'act_1': 'Hồi 1 (Màn bắt ép tập thể): Cả dòng họ nhà chồng kéo đến ăn chực, ép con dâu ký giấy chuyển nhượng tài sản 30 tỷ với giá rẻ mạt 2 tỷ.', 'act_2': 'Hồi 2 (Kế hoạch 24 giờ): Nữ chính giả vờ cần thời gian sang tên, âm thầm liên hệ khách mua đại gia thanh toán toàn bộ 30 tỷ tiền mặt trong buổi sáng hôm sau tại phòng công chứng.', 'act_3': 'Hồi 3 (Rút củi đáy nồi): Trưa hôm sau, khi họ hàng dọn đồ đến để chuẩn bị vào ở, đội ngũ dọn nhà chuyên nghiệp và chủ nhà mới lực lưỡng đã đứng chặn ở cửa; Tống Lam bế con gái lên máy bay di cư vào Nam sinh sống.'}, 'plot_twist': 'Điểm bẻ lái cốt lõi: 2 tỷ tiền cọc mà họ hàng gom góp để mua căn nhà thực chất là tiền vay nặng lãi; khi căn nhà bị bán mất, họ mất sạch suất học, ôm khoản nợ lãi mẹ đẻ lãi con và quay sang đập phá nhà của gã chồng.', 'mastery_takeaways': ['Chiến thuật Rút củi đáy nồi (Removing the Firewood from under the Cauldron): Không tranh cãi lý lẽ với kẻ tham lam, trực tiếp thanh lý tài sản biến thành tiền mặt khiến đối phương mất hoàn toàn mục tiêu tấn công.', 'Sự dứt khoát bảo vệ con cái: Bản năng người mẹ bảo vệ tương lai học hành của con gái trước sự bất công gia trưởng.', 'Mẹo chuyển thể Audio TikTok: Tiếng loa sân bay phát thông báo chuyến bay cất cánh, giọng đọc nữ nhẹ nhõm, thanh thản nhìn qua khung cửa sổ mây trời.'], 'title_vn': 'Cuộc Chiến Căn Hộ Trường Học Tuyến Một', 'genre': 'Hiện đại đô thị / Tranh đoạt nhà cửa / Cực phẩm gia đình / Rút củi đáy nồi', 'golden_hook': "Chồng tôi ném bản hợp đồng chuyển nhượng hai tỷ lên bàn ăn: 'Ký đi! Căn nhà trường điểm này phải để cho cháu đích tôn của anh vào lớp một, con gái mình học trường làng ở đâu chẳng được!'.", 'author_platform': 'Tri Hồ - Zhihu (Hiện thực xã hội)', 'core_lessons': ['Chiến thuật Rút củi đáy nồi (Removing the Firewood from under the Cauldron): Không tranh cãi lý lẽ với kẻ tham lam, trực tiếp thanh lý tài sản biến thành tiền mặt khiến đối phương mất hoàn toàn mục tiêu tấn công.', 'Sự dứt khoát bảo vệ con cái: Bản năng người mẹ bảo vệ tương lai học hành của con gái trước sự bất công gia trưởng.', 'Mẹo chuyển thể Audio TikTok: Tiếng loa sân bay phát thông báo chuyến bay cất cánh, giọng đọc nữ nhẹ nhõm, thanh thản nhìn qua khung cửa sổ mây trời.']}]
